// Serves the static production build the way a static host would.
//
// Files in `.output/public` are served as-is. App routes such as `/chat/alice`
// fall back to `index.html` (the CSP-patched shell). Missing asset files return
// 404 instead of the shell.
//
// Security headers are read from `_headers` (generated by the CSP build) and
// applied to every response, so this server is enough behind an external TLS
// reverse proxy. It is not a replacement for one.

import { createServer } from "node:http"
import { readFile, stat } from "node:fs/promises"
import { extname, join, resolve, sep } from "node:path"

const ROOT = resolve(process.cwd(), ".output", "public")
const PORT = Number(process.env.PORT ?? 4173)

async function loadSecurityHeaders() {
	try {
		const raw = await readFile(join(ROOT, "_headers"), "utf8")
		const headers = {}
		for (const line of raw.split("\n")) {
			const trimmed = line.trim()
			if (!trimmed || trimmed === "/*" || trimmed.startsWith("#")) continue
			const separator = trimmed.indexOf(":")
			if (separator <= 0) continue
			headers[trimmed.slice(0, separator).trim()] = trimmed
				.slice(separator + 1)
				.trim()
		}
		return headers
	} catch {
		return {}
	}
}

const SECURITY_HEADERS = await loadSecurityHeaders()

const CONTENT_TYPES = {
	".html": "text/html; charset=utf-8",
	".js": "text/javascript; charset=utf-8",
	".css": "text/css; charset=utf-8",
	".json": "application/json; charset=utf-8",
	".svg": "image/svg+xml",
	".png": "image/png",
	".jpg": "image/jpeg",
	".webp": "image/webp",
	".woff2": "font/woff2",
	".ico": "image/x-icon",
	".txt": "text/plain; charset=utf-8",
}

async function resolveFile(pathname) {
	const candidate = resolve(ROOT, `.${pathname}`)
	if (candidate !== ROOT && !candidate.startsWith(ROOT + sep)) return null
	try {
		const info = await stat(candidate)
		if (info.isFile()) return candidate
		if (info.isDirectory()) return join(candidate, "index.html")
	} catch {
		// Fall through to the SPA fallback for navigation requests.
	}
	return null
}

const server = createServer(async (request, response) => {
	const url = new URL(request.url ?? "/", "http://localhost")
	const pathname = decodeURIComponent(url.pathname)
	if (pathname === "/healthz") {
		response.writeHead(200, {
			...SECURITY_HEADERS,
			"content-type": "text/plain; charset=utf-8",
		})
		response.end("ok\n")
		return
	}
	if (pathname === "/_headers") {
		response.writeHead(404, { "content-type": "text/plain; charset=utf-8" })
		response.end("Not found")
		return
	}
	let file = await resolveFile(pathname)

	if (!file) {
		if (extname(pathname)) {
			response.writeHead(404, { "content-type": "text/plain; charset=utf-8" })
			response.end("Not found")
			return
		}
		file = join(ROOT, "index.html")
	}

	try {
		const body = await readFile(file)
		response.writeHead(200, {
			...SECURITY_HEADERS,
			"content-type": CONTENT_TYPES[extname(file)] ?? "application/octet-stream",
		})
		response.end(body)
	} catch {
		response.writeHead(404, { "content-type": "text/plain; charset=utf-8" })
		response.end("Not found")
	}
})

server.listen(PORT, () => {
	console.log(`Serving ${ROOT} at http://localhost:${PORT} (SPA fallback enabled)`)
})
